{
  "families": [
    {
      "budget_share": 0.5,
      "family": "pipelined",
      "ranges": [
        {
          "choices": [
            "trunc",
            "round"
          ],
          "high": 4,
          "low": 0,
          "param": "frac_guard"
        },
        {
          "choices": [
            "trunc",
            "round"
          ],
          "high": 4,
          "low": -2,
          "param": "angle_guard"
        },
        {
          "choices": [
            "trunc",
            "round"
          ],
          "high": 14,
          "low": 12,
          "param": "data_width"
        },
        {
          "choices": [
            "trunc",
            "round"
          ],
          "high": 16,
          "low": 12,
          "param": "n_iter"
        }
      ],
      "why": "Fully pipelined gives 1 result/cycle, easily meeting the >=1 MSPS throughput constraint at modest Fmax. N=12-16 with W=12-14 and small guards should satisfy max_abs_err <= 2^-10 while keeping area low. This is the primary low-area candidate."
    },
    {
      "budget_share": 0.5,
      "family": "pipelined_m",
      "ranges": [
        {
          "choices": [
            "trunc",
            "round"
          ],
          "high": 4,
          "low": 0,
          "param": "frac_guard"
        },
        {
          "choices": [
            "trunc",
            "round"
          ],
          "high": 4,
          "low": -2,
          "param": "angle_guard"
        },
        {
          "choices": [
            "trunc",
            "round"
          ],
          "high": 14,
          "low": 12,
          "param": "data_width"
        },
        {
          "choices": [
            "trunc",
            "round"
          ],
          "high": 16,
          "low": 12,
          "param": "n_iter"
        },
        {
          "choices": [
            "trunc",
            "round"
          ],
          "high": 4,
          "low": 2,
          "param": "m"
        }
      ],
      "why": "Registering every m stages (m=2-4) reduces FF count versus fully pipelined while still delivering 1 result/cycle. This trades a small latency increase for lower area, potentially finding points on the Pareto front with fewer FFs at similar LUT count. m=2-4 keeps latency reasonable while cutting pipeline registers."
    }
  ],
  "rationale": "The spec demands >=1 MSPS throughput and max_abs_err <= 2^-10, with area (LUTs+FFs) as the primary objective. Both pipelined and pipelined_m deliver 1 result/cycle, so throughput is met as long as Fmax >= 1 MHz (trivially satisfied). The accuracy constraint (2^-10) requires sufficient n_iter and data_width: N=12-14 iterations with W=12-14 and modest guards should comfortably meet 2^-10 error. I focus on the low end of data_width and n_iter to minimize area, with small guard bits (angle_guard -2..4, frac_guard 0..4) to explore the accuracy/area trade-off. pipelined_m with m=2-4 can reduce FF count by sharing pipeline registers, potentially yielding lower total area than fully pipelined at the same accuracy. Splitting budget 50/50 between the two families lets the optimizer find the best area point in each and compare on the merged Pareto front."
}
